# Generated by scripts/packaging/formula.ts in ome-labs/ome for each release; do not edit by hand.
class Ome < Formula
  desc "Private k-of-n multisig on Aztec with threshold viewing"
  homepage "https://ome.network"
  version "0.2.0"
  license "Apache-2.0"

  depends_on "node@24"

  on_macos do
    on_arm do
      url "https://github.com/ome-labs/ome/releases/download/v0.2.0/ome-0.2.0-darwin-arm64.tar.gz"
      sha256 "6a4fbe783f90bd167db9205d39d2ff4560466487ba268f2685e76de278d1d070"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/ome-labs/ome/releases/download/v0.2.0/ome-0.2.0-linux-x64.tar.gz"
      sha256 "7315661fa8916d7a836d935848f1d97da44e613972342659f99b45738d554795"
    end
    on_arm do
      url "https://github.com/ome-labs/ome/releases/download/v0.2.0/ome-0.2.0-linux-arm64.tar.gz"
      sha256 "b4930051e316dddd3a7a62b92e4556543fe8914f3774683a3490e2d916886be3"
    end
  end

  def install
    libexec.install Dir["*"]
    # The daemon runs with Homebrew's Node, also when a login service starts it without PATH.
    inreplace libexec/"bin/omed", 'node_default=""', %Q(node_default="#{formula_opt_bin("node@24")}/node")
    bin.install_symlink libexec/"bin/ome", libexec/"bin/omed", libexec/"bin/ome-keeper"
  end

  def caveats
    <<~EOS
      Create a profile with:
        ome init
      Keep your keeper online while your laptop sleeps by running the daemon as a login service:
        ome daemon install-service
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/ome --version")
    assert_match version.to_s, shell_output("#{bin}/ome-keeper --version")
  end
end
